// ------------------------------------------------------------------ dynamic cloud quotes pool (RAM only)
static void setOfflineStandbyQuote() {
  quotes.clear();
  Quote q;
  q.idx = "!";
  q.content = "No cloud prescripts loaded.\nConnect to Wi-Fi to stream live\nprescripts from Cloudflare.";
